// Secure application with security best practices implemented
// This version includes protection against common Node.js vulnerabilities

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security headers with Helmet
app.use(helmet());

// 2. HTTPS enforcement (Strict-Transport-Security)
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year in seconds
  includeSubDomains: true,
  preload: true,
}));

// 3. CORS configuration - restrict to allowed origins
const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
}));

// 4. Rate limiting - prevent brute force and DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minute window
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// 5. Body parser middleware with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================
// ROUTES WITH VALIDATION
// ============================================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Secured users endpoint with input validation
app.get('/users',
  // Input validation
  query('skip').optional().isInt({ min: 0 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid input parameters',
        details: errors.array() 
      });
    }

    // Example users - in production, fetch from secured database
    const allUsers = [
      { id: 1, name: 'Alice' }, // Removed sensitive email field
      { id: 2, name: 'Bob' },
    ];

    const skip = req.query.skip || 0;
    const limit = req.query.limit || 10;
    const users = allUsers.slice(skip, skip + limit);

    res.json({
      data: users,
      total: allUsers.length,
      skip,
      limit,
    });
  }
);

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist.',
  });
});

// Error handling middleware - must be last
app.use((err, req, res, next) => {
  const statusCode = err.status || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  console.error({
    error: err.message,
    status: statusCode,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    ...(isDevelopment && { stack: err.stack }),
  });

  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`[${new Date().toISOString()}] Server running on ${HOST}:${PORT}`);
  console.log(`[${new Date().toISOString()}] Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Best Practices Guide for Node.js

## 1. Environment Configuration

**✅ DO:**
```javascript
// Load environment variables from .env file
require('dotenv').config();

const dbUrl = process.env.DATABASE_URL;
const apiKey = process.env.API_KEY;
```

**❌ DON'T:**
```javascript
// Never hardcode secrets
const dbUrl = 'postgres://admin:password@db:5432/prod';
const apiKey = 'sk-secret-key-12345';
```

---

## 2. Dependency Management

**✅ DO:**
```bash
# Run security audits regularly
npm audit

# Fix vulnerabilities automatically
npm audit fix

# Install dependencies from lock file for reproducibility
npm ci
```

**❌ DON'T:**
```bash
# Avoid using npm install in production (use npm ci instead)
npm install

# Ignore security warnings
npm audit --audit-level=none
```

---

## 3. Input Validation & Sanitization

**✅ DO:**
```javascript
const { query, body, validationResult } = require('express-validator');

app.post('/users', 
  body('email').isEmail().normalizeEmail(),
  body('name').trim().escape().notEmpty(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process validated data
  }
);
```

**❌ DON'T:**
```javascript
// Never trust user input
app.post('/users', (req, res) => {
  const user = req.body.name; // Dangerous!
  db.query(`INSERT INTO users (name) VALUES ('${user}')`); // SQL Injection!
});
```

---

## 4. SQL Injection Prevention

**✅ DO:**
```javascript
// Use parameterized queries
db.query('SELECT * FROM users WHERE id = ?', [userId], (err, results) => {
  // ...
});

// Or with async/await
const results = await db.query('SELECT * FROM users WHERE id = $1', [userId]);
```

**❌ DON'T:**
```javascript
// String concatenation is vulnerable
db.query(`SELECT * FROM users WHERE id = ${userId}`);
```

---

## 5. Authentication & Authorization

**✅ DO:**
```javascript
const jwt = require('jsonwebtoken');

// Protect routes with middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
};

app.get('/admin', authenticate, (req, res) => {
  // Only authenticated users reach here
});
```

**❌ DON'T:**
```javascript
// No authentication on sensitive endpoints
app.get('/admin/users', (req, res) => {
  res.json(allUsers); // Everyone can access!
});
```

---

## 6. Error Handling

**✅ DO:**
```javascript
app.use((err, req, res, next) => {
  console.error(err); // Log for debugging

  // Never expose implementation details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({ error: 'Internal Server Error' });
  }

  res.status(500).json({ error: err.message, stack: err.stack });
});
```

**❌ DON'T:**
```javascript
// Exposing stack traces leaks information
app.use((err, req, res, next) => {
  res.status(500).json({ 
    error: err.message,
    stack: err.stack, // Attacker can see system details!
    file: err.filename,
    line: err.lineno
  });
});
```

---

## 7. Password Security

**✅ DO:**
```javascript
const bcrypt = require('bcrypt');

// Hash passwords with salt
const hashedPassword = await bcrypt.hash(plainPassword, 10);

// Verify passwords
const isValid = await bcrypt.compare(inputPassword, hashedPassword);
```

**❌ DON'T:**
```javascript
// Never store plain text passwords
db.query('INSERT INTO users (password) VALUES (?)', [plainPassword]);

// Never use weak hashing
const hash = require('crypto').createHash('md5').update(password).digest('hex');
```

---

## 8. API Security

**✅ DO:**
```javascript
// Rate limiting
const rateLimit = require('express-rate-limit');
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

// CORS restrictions
app.use(cors({ origin: process.env.ALLOWED_ORIGINS.split(',') }));

// Security headers
const helmet = require('helmet');
app.use(helmet());

// Disable unnecessary headers
app.disable('x-powered-by');
```

**❌ DON'T:**
```javascript
// Allowing unrestricted CORS
app.use(cors()); // Accepts all origins!

// No rate limiting
// No security headers
```

---

## 9. Logging & Monitoring

**✅ DO:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Log security events
logger.warn('Suspicious activity detected', { ip, userId, action });
```

**❌ DON'T:**
```javascript
// Using console.log for sensitive operations
console.log('User login:', username, password); // Exposure!
```

---

## 10. Data Protection

**✅ DO:**
```javascript
// Encrypt sensitive data at rest
const crypto = require('crypto');

function encrypt(text, key) {
  const cipher = crypto.createCipher('aes-256-cbc', key);
  return cipher.update(text, 'utf8', 'hex') + cipher.final('hex');
}

// Use HTTPS in production
// Use secure cookies
res.cookie('sessionId', token, {
  httpOnly: true,
  secure: true, // HTTPS only
  sameSite: 'strict',
  maxAge: 3600000
});
```

**❌ DON'T:**
```javascript
// Storing sensitive data in plain text
// Sending credentials over HTTP
// Using non-httpOnly cookies
```

---

## 11. Dependencies Security

**✅ DO:**
```bash
# Use npm audit to find vulnerabilities
npm audit

# Keep dependencies up to date
npm update

# Use package-lock.json to ensure reproducible installs
npm ci

# Regularly check for outdated packages
npm outdated
```

**Tools to use:**
- `npm audit` - Built-in vulnerability scanner
- `Snyk` - Advanced dependency security
- `Dependabot` - Automated dependency updates
- `OWASP Dependency-Check` - Comprehensive vulnerability database

---

## 12. Common Vulnerabilities (OWASP Top 10)

| Vulnerability | Prevention |
|---|---|
| Injection | Use parameterized queries, input validation |
| Broken Authentication | Strong authentication, JWT/sessions, MFA |
| Sensitive Data Exposure | Encryption, HTTPS, secure headers |
| XML External Entities (XXE) | Disable DTD processing |
| Broken Access Control | Authorization checks, least privilege |
| Security Misconfiguration | Security headers, minimal dependencies |
| XSS | Input sanitization, CSP headers |
| Insecure Deserialization | Avoid unsafe parsing, validate input |
| Using Components with Known Vulnerabilities | Keep dependencies updated, `npm audit` |
| Insufficient Logging & Monitoring | Comprehensive logging, alerts |

---

## Quick Security Checklist

- [ ] Use environment variables for all secrets
- [ ] Never commit `.env` files
- [ ] Add `.env*` to `.gitignore`
- [ ] Use HTTPS in production
- [ ] Implement rate limiting
- [ ] Add input validation
- [ ] Use helmet.js for security headers
- [ ] Configure CORS properly
- [ ] Hash passwords with bcrypt
- [ ] Implement authentication middleware
- [ ] Add comprehensive error handling
- [ ] Run `npm audit` regularly
- [ ] Use parameterized queries
- [ ] Enable security logging
- [ ] Regular security testing
- [ ] Keep Node.js and dependencies updated

---

## Resources

- OWASP Top 10: https://owasp.org/www-project-top-ten/
- Node.js Security Best Practices: https://nodejs.org/en/docs/guides/security/
- Express Security: https://expressjs.com/en/advanced/best-practice-security.html
- npm Security Advisories: https://www.npmjs.com/advisories
- Snyk: https://snyk.io/

