// Secure Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers (Helmet)
app.use(helmet());

// 2. Logging
app.use(morgan('combined'));

// 3. CORS Configuration
const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'https://example.com').split(',');
app.use(cors({
  origin: allowedOrigins,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 4. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// 5. Body Parser (for JSON/form data)
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

const isAuthenticated = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized: Missing or invalid authorization header' });
  }

  // TODO: Validate JWT token properly
  // const token = authHeader.substring(7);
  // if (!validateToken(token)) {
  //   return res.status(401).json({ error: 'Unauthorized: Invalid token' });
  // }

  next();
};

// ============================================
// ROUTES
// ============================================

// Health check (no auth required)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with authentication and validation
app.get('/users',
  // Input Validation
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  // Authentication
  isAuthenticated,
  // Handler
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    // Return non-sensitive data only
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    res.json({
      data: users.slice(offset, offset + limit),
      total: users.length,
      limit,
      offset
    });
  }
);

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Centralized Error Handler (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', err);

  const isProduction = process.env.NODE_ENV === 'production';
  const statusCode = err.statusCode || err.status || 500;

  res.status(statusCode).json({
    error: isProduction ? 'Internal Server Error' : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Only start server if this file is run directly
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`✓ Server running on port ${PORT} in ${NODE_ENV} mode`);
    console.log(`✓ CORS enabled for: ${allowedOrigins.join(', ')}`);
  });
}

module.exports = app;

// Example tests for security features (using Jest and Supertest)
const request = require('supertest');
const app = require('./app.secure');

describe('Security Headers', () => {
  it('should include security headers', async () => {
    const response = await request(app).get('/health');

    expect(response.headers['x-content-type-options']).toBe('nosniff');
    expect(response.headers['x-frame-options']).toBe('DENY');
    expect(response.headers['x-xss-protection']).toBe('1; mode=block');
    expect(response.headers['content-security-policy']).toBeDefined();
    expect(response.headers['strict-transport-security']).toBeDefined();
  });

  it('should not expose server information', async () => {
    const response = await request(app).get('/health');

    expect(response.headers['x-powered-by']).toBeUndefined();
    expect(response.headers['server']).toBeUndefined();
  });
});

describe('CORS', () => {
  it('should include CORS headers', async () => {
    const response = await request(app)
      .get('/health')
      .set('Origin', 'https://example.com');

    expect(response.headers['access-control-allow-origin']).toBeDefined();
  });

  it('should reject unauthorized origins', async () => {
    const response = await request(app)
      .get('/health')
      .set('Origin', 'https://evil.com');

    // Should not allow unauthorized origins
    expect(response.headers['access-control-allow-origin']).not.toBe('https://evil.com');
  });
});

describe('Authentication', () => {
  it('should require authentication for /users endpoint', async () => {
    const response = await request(app).get('/users');

    expect(response.status).toBe(401);
    expect(response.body.error).toBe('Unauthorized: Missing or invalid authorization header');
  });

  it('should allow access with Bearer token', async () => {
    const response = await request(app)
      .get('/users')
      .set('Authorization', 'Bearer valid-token');

    expect(response.status).toBe(200);
    expect(response.body.data).toBeDefined();
  });
});

describe('Input Validation', () => {
  it('should validate limit parameter', async () => {
    const response = await request(app)
      .get('/users?limit=invalid')
      .set('Authorization', 'Bearer token');

    expect(response.status).toBe(400);
    expect(response.body.errors).toBeDefined();
  });

  it('should reject limit > 100', async () => {
    const response = await request(app)
      .get('/users?limit=101')
      .set('Authorization', 'Bearer token');

    expect(response.status).toBe(400);
  });

  it('should accept valid limit', async () => {
    const response = await request(app)
      .get('/users?limit=10&offset=0')
      .set('Authorization', 'Bearer token');

    expect(response.status).toBe(200);
    expect(response.body.limit).toBe(10);
  });
});

describe('Rate Limiting', () => {
  it('should rate limit after max requests', async () => {
    // This test would need to be more sophisticated in practice
    // Testing rate limiting requires making many requests
    const response = await request(app).get('/health');

    expect(response.headers['ratelimit-limit']).toBeDefined();
    expect(response.headers['ratelimit-remaining']).toBeDefined();
  });
});

describe('Error Handling', () => {
  it('should handle 404 errors', async () => {
    const response = await request(app).get('/nonexistent');

    expect(response.status).toBe(404);
    expect(response.body.error).toBe('Not Found');
  });

  it('should not expose stack traces in production', async () => {
    process.env.NODE_ENV = 'production';

    const response = await request(app).get('/nonexistent');

    expect(response.body.stack).toBeUndefined();

    process.env.NODE_ENV = 'development';
  });
});

describe('Sensitive Data', () => {
  it('should not expose email addresses without authentication', async () => {
    const response = await request(app).get('/users');

    expect(response.status).toBe(401);
  });

  it('should not return email addresses in user list', async () => {
    const response = await request(app)
      .get('/users')
      .set('Authorization', 'Bearer token');

    expect(response.status).toBe(200);

    // Verify no email fields in response
    response.body.data.forEach(user => {
      expect(user.email).toBeUndefined();
    });
  });
});

describe('Health Check', () => {
  it('should return health status', async () => {
    const response = await request(app).get('/health');

    expect(response.status).toBe(200);
    expect(response.body.status).toBe('ok');
    expect(response.body.timestamp).toBeDefined();
  });
});

