// Secure Express Application - Remediated Version
// Implements security best practices

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const morgan = require('morgan');

const app = express();
const nodeEnv = process.env.NODE_ENV || 'development';

// ============= SECURITY MIDDLEWARE =============

// 1. Security Headers
app.use(helmet());

// 2. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// 3. Request Logging
if (nodeEnv === 'production') {
  app.use(morgan('combined'));
} else {
  app.use(morgan('dev'));
}

// 4. Body Parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 6. HTTPS redirect in production
app.use((req, res, next) => {
  if (nodeEnv === 'production' && !req.secure && req.get('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.get('host')}${req.originalUrl}`);
  }
  next();
});

// ============= ROUTES =============

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: nodeEnv 
  });
});

// Protected endpoint - requires authentication
// Note: This is a placeholder. Implement proper JWT/OAuth2 authentication
app.get('/users', (req, res) => {
  // TODO: Implement authentication verification
  // if (!req.headers.authorization) {
  //   return res.status(401).json({ error: 'Unauthorized' });
  // }

  // Only return non-sensitive fields
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// ============= ERROR HANDLING =============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = nodeEnv === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ============= SERVER START =============

const port = process.env.PORT || 3000;
const server = app.listen(port, () => {
  console.log(`Server running on port ${port} (${nodeEnv})`);
  console.log('Security middleware enabled: helmet, rate-limiting, sanitization');
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

