// Secure version of the application with recommended security fixes applied

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const winston = require('winston');
require('dotenv').config();

const app = express();

// ===== LOGGING SETUP =====
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ===== SECURITY MIDDLEWARE =====

// Security headers
app.use(helmet());

// CORS configuration - restrict to allowed origins
app.use(cors({
  origin: (origin, callback) => {
    const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// HTTPS enforcement (for production)
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// Body parser middleware
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ===== AUTHENTICATION MIDDLEWARE =====
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn('Unauthorized access attempt - no token provided');
    return res.status(401).json({ error: 'Access token required' });
  }

  // In production, verify JWT signature
  try {
    // TODO: Replace with actual JWT verification
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // req.user = decoded;
    req.user = { id: 1, role: 'admin' }; // Placeholder
    next();
  } catch (err) {
    logger.warn(`Unauthorized access attempt - invalid token: ${err.message}`);
    res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ===== AUTHORIZATION MIDDLEWARE =====
const requireRole = (roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      logger.warn(`Forbidden access attempt - insufficient permissions for user ${req.user?.id}`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// ===== ROUTES =====

// Health check (public, no auth required)
app.get('/health', (req, res) => {
  logger.debug('Health check');
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Get users (requires authentication and admin role)
app.get('/users',
  authenticateToken,
  requireRole(['admin']),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn(`Invalid query parameters: ${JSON.stringify(errors.array())}`);
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const limit = req.query.limit || 10;
      const offset = req.query.offset || 0;

      logger.info(`User list accessed by admin ${req.user.id} (limit: ${limit}, offset: ${offset})`);

      // Return sanitized user data (no sensitive fields)
      const users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ].slice(offset, offset + limit);

      res.json({
        data: users,
        limit,
        offset,
        total: 2
      });
    } catch (err) {
      logger.error(`Error fetching users: ${err.message}`, err);
      res.status(500).json({ error: 'Internal Server Error' });
    }
  }
);

// ===== ERROR HANDLING =====

// 404 handler
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error(`Unhandled error: ${err.message}`, {
    error: err,
    method: req.method,
    path: req.path,
    ip: req.ip
  });

  const statusCode = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ===== SERVER STARTUP =====

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// ===== GRACEFUL SHUTDOWN =====

process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

