const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Use Helmet.js for setting secure HTTP headers
app.use(helmet());

// 2. Configure CORS properly
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST'],
}));

// 3. Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// 4. Body parser with size limit to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ========== ROUTES ==========

// Health check endpoint
app.get('/health', (req, res) => {
  const checks = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development',
  };
  res.json(checks);
});

// Users endpoint - SECURED
// Note: Should add authentication/authorization in production
// For now, returns minimal data without email exposure
app.get('/users', (req, res) => {
  // In production, verify user has permission to access this data
  // const user = req.user; // from authentication middleware
  // if (!user || !user.hasPermission('read:users')) {
  //   return res.status(403).json({ error: 'Forbidden' });
  // }

  res.json([
    { id: 1, name: 'Alice' }, // Removed email - avoid PII exposure
    { id: 2, name: 'Bob' },
  ]);
});

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
    // Don't log sensitive data
  });

  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(status).json({
    error: message,
    // Only expose stack traces in development
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ========== SERVER START ==========

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

