// authentication-middleware.example.js
// Example authentication middleware for protecting endpoints

const jwt = require('jsonwebtoken');

/**
 * Verify JWT token from request headers
 * Usage: app.get('/protected', authenticateToken, (req, res) => {...})
 */
function authenticateToken(req, res, next) {
  try {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

    if (!token) {
      return res.status(401).json({
        error: 'Access token required',
        code: 'NO_TOKEN'
      });
    }

    jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
      if (err) {
        // Token expired or invalid
        if (err.name === 'TokenExpiredError') {
          return res.status(401).json({
            error: 'Token expired',
            code: 'TOKEN_EXPIRED'
          });
        }
        return res.status(403).json({
          error: 'Invalid token',
          code: 'INVALID_TOKEN'
        });
      }
      req.user = user;
      next();
    });
  } catch (error) {
    console.error('Auth error:', error.message);
    res.status(500).json({ error: 'Authentication error' });
  }
}

/**
 * Verify user has required role/permission
 * Usage: app.delete('/users/:id', authenticateToken, authorize('admin'), ...)
 */
function authorize(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({
        error: 'Forbidden',
        message: `Required role: ${allowedRoles.join(', ')}`
      });
    }

    next();
  };
}

/**
 * Create JWT token (use in login endpoint)
 */
function generateToken(user) {
  return jwt.sign(
    {
      id: user.id,
      email: user.email,
      role: user.role
    },
    process.env.JWT_SECRET,
    { expiresIn: '1h' } // Token expires in 1 hour
  );
}

module.exports = {
  authenticateToken,
  authorize,
  generateToken
};

