// Secure version of the application with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');

const app = express();

// ===== Security Middleware =====

// 1. Helmet - Set HTTP security headers
app.use(helmet());

// 2. CORS - Configure Cross-Origin Resource Sharing
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// 3. Rate Limiting - Protect against brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// 4. Request Logging - Morgan for audit trail
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 5. Body Parser - Built-in middleware for JSON
app.use(express.json());

// ===== Authentication Middleware (Example) =====
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // TODO: Implement proper JWT validation
  // const verified = jwt.verify(token, process.env.JWT_SECRET);
  // if (!verified) return res.status(403).json({ error: 'Invalid token' });

  next();
};

// ===== Routes =====

// Health check endpoint (no authentication needed)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Protected users endpoint - requires authentication
app.get('/users', authenticateToken, (req, res) => {
  // In production, fetch from database with proper authorization checks
  res.json([
    { id: 1, name: 'Alice' }, // Email removed - only expose necessary data
    { id: 2, name: 'Bob' },
  ]);
});

// Example of input validation
app.post('/users', authenticateToken, [
  body('name').trim().escape().notEmpty().withMessage('Name is required'),
  body('email').isEmail().withMessage('Valid email is required')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Process validated input
  res.status(201).json({ message: 'User created', data: req.body });
});

// ===== Error Handling Middleware =====

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('[ERROR]', err);

  // Don't expose sensitive error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(err.status || 500).json({ error: message });
});

// ===== Server Startup =====

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

